// TestJanitorRegistry covers the registry mechanics (artwork D8): tasks are
// registered with intervals, the boot-run executes each enabled task exactly
// once in order, and a zero interval — the knob's off position — skips ONLY
// that task while the others boot and tick unchanged.
func TestJanitorRegistry(t *testing.T) {
	var streams, art atomicCounter
	j := newJanitor(
		janitorTask{name: "streams", interval: 5 * time.Millisecond, fn: func(context.Context) { streams.add(1) }},
		// The art task as the env knob leaves it: interval 0 disables it
		// alone — no boot-run, no ticks, streams untouched.
		janitorTask{name: "art", interval: 0, fn: func(context.Context) { art.add(1) }},
	)

	j.runBoot(context.Background())
	if got := streams.load(); got != 1 {
		t.Fatalf("boot: streams ran %d times, want 1", got)
	}
	if got := art.load(); got != 0 {
		t.Fatalf("boot: disabled art ran %d times, want 0", got)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Millisecond)
	defer cancel()
	j.run(ctx)
	if got := streams.load(); got < 2 {
		t.Fatalf("run: streams ticked %d times, want >= 2 (boot + at least one tick)", got)
	}
	if got := art.load(); got != 0 {
		t.Fatalf("run: knob-off art ran %d times, want 0 (only art is disabled)", got)
	}
}

// TestArtTaskOrphanSweep drives the art settle+GC task (artwork) through the
// registry's task shape over a real store and blob tree: the replace-by-
// re-enrich orphan is reclaimed with its sha-dir, a deleted upload's pair is
// swept once its override goes, a gate-flipped (but still live) URL
// survives, and both repair legs — the row whose bytes file is missing and
// the bytes dir with no row — do their work.
func TestArtTaskOrphanSweep(t *testing.T) {
	ctx := context.Background()
	st := openJanitorStore(t)
	root := t.TempDir()
	svc := art.NewService(st, root)

	posterA := janitorJPEG(t, 0xA0)
	posterB := janitorJPEG(t, 0xB0)
	film := janitorJPEG(t, 0xF0)
	shaA, shaB, shaFilm := sha256HexOf(posterA), sha256HexOf(posterB), sha256HexOf(film)
	srv, fail := newJanitorUpstream(t, map[string][]byte{
		"/a.jpg": posterA, "/b.jpg": posterB, "/film.jpg": film,
	})

	lib, err := st.CreateLibrary(ctx, "serial", "/media/serials", "Serials")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putSeriesPoster(t, st, lib, "Show", artDocPoster(srv.URL+"/a.jpg"))
	if err := st.PutItem(ctx, store.Item{
		ModuleID: "serial", LibraryID: lib, FileID: "film-1", RelativePath: "Film.mkv",
		MediaType: "movie", Document: artDocPoster(srv.URL + "/film.jpg"), SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutItem: %v", err)
	}

	// The art task as the registry carries it: the settle pass runs at its
	// (knob-configured) interval; the boot-run is the same pass. The task
	// wrapper owns the error translation (log-and-continue cmd-side).
	artTask := janitorTask{name: "art", interval: time.Hour, fn: func(ctx context.Context) {
		if err := svc.Settle(ctx); err != nil {
			t.Errorf("art settle: %v", err)
		}
	}}
	runTask := func() {
		t.Helper()
		j := newJanitor(artTask)
		j.runBoot(ctx)
	}
	runTask()
	if _, err := os.Stat(filepath.Join(root, shaA, "original.jpeg")); err != nil {
		t.Fatalf("series poster not settled: %v", err)
	}
	if _, err := os.Stat(filepath.Join(root, shaFilm, "original.jpeg")); err != nil {
		t.Fatalf("film poster (non-series item) not settled: %v", err)
	}

	// Re-enrich replaces the series poster: the old URL leaves the live
	// documents, so the next pass reclaims its row and its sha-dir while the
	// new entry survives.
	putSeriesPoster(t, st, lib, "Show", artDocPoster(srv.URL+"/b.jpg"))
	runTask()
	assertFetchShas(t, st, map[string]bool{shaB: true, shaFilm: true})
	if _, err := os.Stat(filepath.Join(root, shaA)); !os.IsNotExist(err) {
		t.Fatalf("old sha-dir still on disk after re-enrich (err = %v)", err)
	}
	if _, err := os.Stat(filepath.Join(root, shaB, "original.jpeg")); err != nil {
		t.Fatalf("new poster not settled: %v", err)
	}

	// Gate-flip survival: the walk reads documents, never gates — the film
	// URL stays live even when its namespace is muted, so the pass neither
	// deletes the row nor the dir.
	runTask()
	assertFetchShas(t, st, map[string]bool{shaB: true, shaFilm: true})
	if _, err := os.Stat(filepath.Join(root, shaFilm, "original.jpeg")); err != nil {
		t.Fatalf("gate-flipped live entry lost: %v", err)
	}

	// Delete-upload: the upload pinned on the series carries no fetch row;
	// the pass sweeps the pair exactly when its override goes.
	token, err := svc.IngestBytes(ctx, seriesIDOf(t, st, lib, "Show"), "series", janitorJPEG(t, 0x55), "")
	if err != nil {
		t.Fatalf("IngestBytes: %v", err)
	}
	shaUpload := token[len("art_"):]
	if _, err := os.Stat(filepath.Join(root, shaUpload, "cropped.jpg")); err != nil {
		t.Fatalf("upload pair not stored: %v", err)
	}
	if err := st.DeleteArtOverride(ctx, seriesIDOf(t, st, lib, "Show"), "series"); err != nil {
		t.Fatalf("DeleteArtOverride: %v", err)
	}
	runTask()
	if _, err := os.Stat(filepath.Join(root, shaUpload)); !os.IsNotExist(err) {
		t.Fatalf("deleted upload's pair still on disk (err = %v)", err)
	}

	// Repair leg 1: a referenced row whose bytes file is missing is dropped.
	// The upstream now fails for the film URL, so the settle cannot quietly
	// re-materialize it — only the repair leg may remove the row.
	if err := os.RemoveAll(filepath.Join(root, shaFilm)); err != nil {
		t.Fatalf("remove film dir: %v", err)
	}
	fail("/film.jpg")
	runTask()
	assertFetchShas(t, st, map[string]bool{shaB: true})

	// Repair leg 2: a bytes dir with no row and no override is swept.
	ghost := sha256HexOf([]byte("never fetched"))
	if err := os.MkdirAll(filepath.Join(root, ghost), 0o755); err != nil {
		t.Fatalf("mkdir ghost: %v", err)
	}
	if err := os.WriteFile(filepath.Join(root, ghost, "original.jpeg"), []byte("junk"), 0o644); err != nil {
		t.Fatalf("write ghost: %v", err)
	}
	runTask()
	if _, err := os.Stat(filepath.Join(root, ghost)); !os.IsNotExist(err) {
		t.Fatalf("orphan bytes dir still on disk (err = %v)", err)
	}
}

// ---- test plumbing ----------------------------------------------------------

// atomicCounter is a tiny thread-safe counter for the registry test.
type atomicCounter struct {
	mu sync.Mutex
	n  int
}

func (c *atomicCounter) add(d int) { c.mu.Lock(); c.n += d; c.mu.Unlock() }
func (c *atomicCounter) load() int { c.mu.Lock(); defer c.mu.Unlock(); return c.n }

// openJanitorStore opens a fresh temp store for the janitor tests.
func openJanitorStore(t *testing.T) *store.Store {
	t.Helper()
	st, err := store.Open(context.Background(), filepath.Join(t.TempDir(), "janitor.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	return st
}

// janitorJPEG encodes a small JPEG whose pixels carry seed — distinct seeds
// never share a content address.
func janitorJPEG(t *testing.T, seed byte) []byte {
	t.Helper()
	img := image.NewRGBA(image.Rect(0, 0, 4, 6))
	for y := 0; y < 6; y++ {
		for x := 0; x < 4; x++ {
			img.Set(x, y, color.RGBA{R: seed, G: uint8(int(seed) + x), B: uint8(int(seed) + y), A: 255})
		}
	}
	var buf bytes.Buffer
	if err := jpeg.Encode(&buf, img, nil); err != nil {
		t.Fatalf("encode jpeg: %v", err)
	}
	return buf.Bytes()
}

// sha256HexOf is the content address of b (the blob dir name).
func sha256HexOf(b []byte) string {
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// janitorUpstream is the settle test's upstream: fixed path → bytes plus a
// per-path failure switch the repair legs flip mid-test.
type janitorUpstream struct {
	*httptest.Server
	mu   sync.Mutex
	fail map[string]bool
}

// newJanitorUpstream serves the given files; missing paths 404. The returned
// func makes a path answer 503 from then on (the repair leg's upstream
// outage).
func newJanitorUpstream(t *testing.T, files map[string][]byte) (*janitorUpstream, func(string)) {
	t.Helper()
	u := &janitorUpstream{fail: map[string]bool{}}
	u.Server = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		u.mu.Lock()
		broken := u.fail[r.URL.Path]
		u.mu.Unlock()
		if broken {
			w.WriteHeader(http.StatusServiceUnavailable)
			return
		}
		body, ok := files[r.URL.Path]
		if !ok {
			w.WriteHeader(http.StatusNotFound)
			return
		}
		_, _ = w.Write(body)
	}))
	t.Cleanup(u.Server.Close)
	return u, func(path string) {
		u.mu.Lock()
		defer u.mu.Unlock()
		u.fail[path] = true
	}
}

// artDocPoster builds the minimal document carrying one namespace poster.
func artDocPoster(posterURL string) json.RawMessage {
	doc := map[string]any{
		"sources": map[string]any{
			"shikimori": map[string]any{"poster": posterURL},
		},
	}
	raw, err := json.Marshal(doc)
	if err != nil {
		panic(err) // literal map cannot fail
	}
	return raw
}

// putSeriesPoster upserts one series row carrying the given poster document.
func putSeriesPoster(t *testing.T, st *store.Store, lib int64, relPath string, doc json.RawMessage) {
	t.Helper()
	if err := st.PutSeries(context.Background(), store.Series{
		ModuleID: "serial", LibraryID: lib, RelativePath: relPath, Document: doc, SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutSeries: %v", err)
	}
}

// seriesIDOf loads the minted series id for (lib, relPath).
func seriesIDOf(t *testing.T, st *store.Store, lib int64, relPath string) string {
	t.Helper()
	sr, err := st.GetSeriesByPath(context.Background(), lib, relPath)
	if err != nil {
		t.Fatalf("GetSeriesByPath: %v", err)
	}
	return sr.ID
}

// assertFetchShas asserts the fetch table's sha set (slices aligned with
// ListArtFetches) equals want exactly.
func assertFetchShas(t *testing.T, st *store.Store, want map[string]bool) {
	t.Helper()
	_, shas, _, err := st.ListArtFetches(context.Background())
	if err != nil {
		t.Fatalf("ListArtFetches: %v", err)
	}
	got := make(map[string]bool, len(shas))
	for _, sha := range shas {
		got[sha] = true
	}
	if len(got) != len(want) {
		t.Fatalf("fetch shas = %v, want %v", got, want)
	}
	for sha := range want {
		if !got[sha] {
			t.Fatalf("fetch shas = %v, want %v (missing %s)", got, want, sha)
		}
	}
}
